def transform(grid):
    h,w=len(grid),len(grid[0]); out=[r[:] for r in grid]
    for r0 in range(h):
      for c0 in range(w):
        color=grid[r0][c0]
        for r1 in range(r0+4,h):
          for c1 in range(c0+4,w):
            if all(grid[r][c]==color for r in range(r0,r1+1) for c in range(c0,c1+1)):
              for r in range(r0,r1+1):
                for c in range(c0,c1+1): out[r][c]=4
    return out
